// PREPARAR MENSAJE DE FIDELIZACIÓN
// =====================================================

// --- CONFIGURACIÓN ---
const LINK_GOOGLE_MAPS = "https://g.page/r/TU_LINK_AQUI/review"; 
const NOMBRE_NEGOCIO = "Brilla Estudio";

// 1. DATOS
const cliente = $('Obtener Datos del Cliente').first().json;
const datosLoop = $('Loop Over Items').item.json;

// 2. CALCULAR PUNTOS
const puntosNuevos = Math.floor(parseFloat(datosLoop.puntos_nuevos || 0));
const saldoAnterior = Math.floor(parseFloat(cliente.puntos_acumulados || 0));
const puntosTotales = saldoAnterior + puntosNuevos;

// 3. CALCULAR VISITAS Y CATEGORÍA 👑
const visitasAnteriores = parseInt(cliente.total_visitas || 0);
const visitasActuales = visitasAnteriores + 1; 

let nuevaCategoria = "Nuevo"; 
if (visitasActuales > 1) nuevaCategoria = "Recurrente";
if (visitasActuales >= 5) nuevaCategoria = "Frecuente";
if (visitasActuales >= 10) nuevaCategoria = "Fiel";
if (visitasActuales >= 15) nuevaCategoria = "VIP";

// 4. SALUDO Y CALL TO ACTION
const nombreCorto = (cliente.nombre || 'Cliente').split(' ')[0];
let saludo = "";
let call_to_action = "";

switch (nuevaCategoria) {
    case "Nuevo":
        saludo = `¡Hola ${nombreCorto}! 🌸\n\nQué alegría haberte tenido por primera vez en ${NOMBRE_NEGOCIO}.`;
        call_to_action = "⭐ *¿Qué te pareció tu primera experiencia?*\nDel 1 al 5, ¿qué nota nos pondrías? 👇";
        break;

    case "Recurrente":
        saludo = `¡Hola de nuevo ${nombreCorto}! ✨\n\nGracias por volver a elegirnos.`;
        call_to_action = "⭐ *Tu opinión nos importa:*\nDel 1 al 5, ¿qué tal estuvo el servicio de hoy? 👇";
        break;

    case "Frecuente":
        saludo = `¡Hola ${nombreCorto}! 💖\n\nSiempre es un placer verte por aquí.`;
        call_to_action = `⭐ *Tu opinión nos ayuda mucho:*\n¿Nos regalarías una reseña en Google?\n👉 ${LINK_GOOGLE_MAPS}`;
        break;

    case "Fiel":
        saludo = `¡Hola ${nombreCorto}! 💎\n\nCliente fiel, gracias por confiar siempre en nosotros.`;
        call_to_action = `⭐ *Ayúdanos a crecer:*\n¿Nos regalarías 5 estrellitas en Google? 🌟\n👉 ${LINK_GOOGLE_MAPS}`;
        break;

    case "VIP":
        saludo = `¡Hola ${nombreCorto}! 👑\n\nGracias por tu lealtad. Eres parte fundamental de ${NOMBRE_NEGOCIO}.`;
        call_to_action = `⭐ *Eres VIP, tu voz vale oro:*\n¿Nos ayudarías con una reseña?\n👉 ${LINK_GOOGLE_MAPS}`;
        break;
}

// 5. PREMIOS
const premiosRaw = $('Leer Premios').all().map(p => p.json);

let mapaPremios = premiosRaw.map(p => {
    const nombre = p['Nombre del Premio'] || p.nombre || "Premio";
    const costo = parseInt(p['Puntos Requeridos'] || p.costo_puntos || 0);
    const activo = p.activo !== false && p.Activo !== false;

    return { 
        nombre, 
        costo, 
        faltan: costo - puntosTotales, 
        esGanado: costo <= puntosTotales,
        activo 
    };
}).filter(p => p.activo && p.costo > 0);

const ganados = mapaPremios.filter(m => m.esGanado).sort((a, b) => b.costo - a.costo);
const pendientes = mapaPremios.filter(m => !m.esGanado).sort((a, b) => a.faltan - b.faltan);

let textoPremios = "";

if (ganados.length > 0) {
    textoPremios += "🎁 *¡YA PUEDES CANJEAR!* 👇\n";
    ganados.slice(0, 3).forEach(m => { 
        textoPremios += `✅ ${m.nombre} *(${m.costo} pts)*\n`; 
    });
    textoPremios += "\n";
}

if (pendientes.length > 0) {
    const titulo = ganados.length > 0 ? "🚀 *Tu siguiente meta:*" : "🎯 *Estás muy cerca de:*";
    textoPremios += `${titulo}\n`;
    pendientes.slice(0, 2).forEach(m => { 
        textoPremios += `🔒 ${m.nombre} *(Te faltan +${m.faltan} pts)*\n`; 
    });
}

// 6. MENSAJE COMPLETO
const mensajeWhatsApp = `${saludo}

💰 *Ganaste +${puntosNuevos} puntos* por tu visita de hoy.

📊 *Tu saldo actual:* ${puntosTotales} puntos

${textoPremios}
${call_to_action}

¡Gracias por preferirnos! 💅`;

// 7. RETORNAR
return {
    json: {
        // Para actualizar CLIENTE
        id_cliente: cliente.id,
        visitas_totales: visitasActuales,
        nueva_categoria: nuevaCategoria,
        puntos_totales: puntosTotales,
        ultima_visita: datosLoop.fecha_cita,

        // Para actualizar CITA
        cita_id: datosLoop.cita_id,
        puntos_enviados: true,
        fecha_puntos_enviados: DateTime.now().setZone('America/Lima').toISO(),

        // Para WHATSAPP
        telefono: cliente.telefono,
        nombre_cliente: cliente.nombre,
        mensaje_whatsapp: mensajeWhatsApp,

        // Debug
        puntos_nuevos: puntosNuevos,
        lista_premios: textoPremios
    }
};

