// =====================================================
// FLUJO 2: FIDELIZACIÓN POST-CITA (Versión Mejorada)
// Usa hora_fin para calcular cuándo terminó el servicio
// Envía mensaje 3+ horas después de hora_fin
// =====================================================

const citas = $input.all().map(item => item.json);
const ahora = DateTime.now().setZone('America/Lima');
const horaActual = ahora.hour;

// ===== CONFIGURACIÓN =====
const HORAS_MINIMAS_DESPUES = 3;   // Esperar 3h después de hora_fin
const HORAS_MAXIMAS = 48;          // No enviar si pasaron más de 48h
const HORA_INICIO_ENVIO = 10;      // No enviar antes de 10 AM
const HORA_FIN_ENVIO = 22;         // No enviar después de 10 PM

// Validar horario de envío
if (horaActual < HORA_INICIO_ENVIO || horaActual >= HORA_FIN_ENVIO) {
    console.log(`⏰ Fuera de horario: ${horaActual}h (permitido ${HORA_INICIO_ENVIO}-${HORA_FIN_ENVIO}h)`);
    return [];
}

console.log('📧 Procesando fidelización post-cita...');
console.log('   Hora actual:', ahora.toFormat('yyyy-MM-dd HH:mm'));
console.log('   Citas a evaluar:', citas.length);

// ===== FILTRAR CITAS VÁLIDAS =====
const citasProcesables = citas.filter(cita => {
    // 1. Solo citas ya completadas
    const estado = (cita.estado || '').toLowerCase();
    if (estado !== 'completada') {
        return false;
    }

    // 2. No procesadas antes
    if (cita.puntos_enviados === true || cita.mensaje_enviado === true) {
        return false;
    }

    // 3. USAR hora_fin como referencia (cuándo terminó el servicio)
    let fechaReferencia;
    if (cita.hora_fin) {
        // Mejor opción: usar hora_fin calculada
        fechaReferencia = cita.hora_fin;
    } else if (cita.fecha_completada) {
        // Fallback: usar fecha_completada
        fechaReferencia = cita.fecha_completada;
    } else if (cita.fecha && cita.duracion_min) {
        // Fallback 2: calcular hora_fin
        const inicio = DateTime.fromISO(cita.fecha).setZone('America/Lima');
        fechaReferencia = inicio.plus({ minutes: parseInt(cita.duracion_min) }).toISO();
    } else {
        console.log('⚠️ Cita', cita.id, 'sin hora_fin ni fecha_completada');
        return false;
    }

    // 4. Calcular horas desde que terminó
    const horaFinCita = DateTime.fromISO(fechaReferencia).setZone('America/Lima');
    const horasPasadas = ahora.diff(horaFinCita, 'hours').hours;

    // 5. Verificar ventana de tiempo (3h - 48h después de terminar)
    if (horasPasadas < HORAS_MINIMAS_DESPUES) {
        console.log('⏳ Muy pronto cita', cita.id, 
            '| Terminó:', horaFinCita.toFormat('HH:mm'),
            '| Solo', Math.round(horasPasadas * 10) / 10, 'h');
        return false;
    }

    if (horasPasadas > HORAS_MAXIMAS) {
        console.log('⚠️ Muy antigua cita', cita.id, '-', Math.round(horasPasadas), 'h');
        return false;
    }

    console.log('✅ Procesar cita', cita.id, 
        '| Servicio:', cita.servicio,
        '| Terminó:', horaFinCita.toFormat('dd/MM HH:mm'),
        '| Hace', Math.round(horasPasadas * 10) / 10, 'h');
    return true;
});

console.log('📋 Total citas para fidelización:', citasProcesables.length);

if (citasProcesables.length === 0) {
    return [];
}

// ===== CALCULAR PUNTOS Y PREPARAR DATOS =====
return citasProcesables.map(cita => {
    // Limpieza de precio (quitar símbolos de moneda)
    let precioTexto = String(cita.precio || '0')
        .replace(/S\/?\./gi, '')  // S/. o S/
        .replace('$', '')
        .replace(/\s/g, '')       // Espacios
        .trim();

    // Convertir coma a punto para decimales
    precioTexto = precioTexto.replace(',', '.');

    let precioFinal = parseFloat(precioTexto);
    if (isNaN(precioFinal) || precioFinal < 0) {
        precioFinal = 0;
        console.log('⚠️ Precio inválido cita', cita.id);
    }

    // Calcular puntos (1 sol = 1 punto)
    const puntosGanados = Math.floor(precioFinal);

    // Extraer ID del cliente (manejar diferentes formatos)
    let clienteId;
    if (Array.isArray(cita.cliente)) {
        clienteId = cita.cliente[0]?.id || cita.cliente[0];
    } else if (typeof cita.cliente === 'object' && cita.cliente !== null) {
        clienteId = cita.cliente.id || cita.cliente;
    } else {
        clienteId = cita.cliente || cita.cliente_id;
    }

    return {
        json: {
            // Datos de la cita
            cita_id: cita.id,
            fecha_cita: cita.fecha,
            hora_fin: cita.hora_fin,
            servicio: cita.servicio,

            // Datos del cliente
            nombre_cliente: cita.nombre_cliente || cita.nombre,
            telefono_cliente: cita.telefono || cita.cliente_telefono,
            id_cliente_enlace: clienteId,
            categoria_id: cita.categoria_id || cita.categoria || null,
            staff_id: cita.staff_id || null,

            // Datos calculados
            precio_original: cita.precio,
            precio_limpio: precioFinal,
            puntos_nuevos: puntosGanados,

            // Timestamp
            procesado_en: ahora.toISO()
        }
    };
});

// PREPARAR MENSAJE DE FIDELIZACIÓN (STAFF)
const LINK_GOOGLE_MAPS = "https://g.page/r/TU_LINK_AQUI/review"; 
const NOMBRE_NEGOCIO = $('Obtener Tipo Fidelización').first().json.nombre || "nuestro salón";

const cliente = $('Obtener Datos del Cliente').first().json;
const datosLoop = $('Loop Over Items').item.json;
const puntosCat = $('Leer Puntos Categoria Actualizados (Despues)').first()?.json || { puntos_categoria: 0, visitas_categoria: 1 };
const categoriaNombre = datosLoop.categoria_id || "el servicio";

const puntosNuevos = Math.floor(parseFloat(datosLoop.puntos_nuevos || 0));
const puntosTotales = Math.floor(parseFloat(puntosCat.puntos_categoria || 0));
const visitasActuales = parseInt(puntosCat.visitas_categoria || 1);

const nombreCorto = (cliente.nombre || 'Cliente').split(' ')[0];
let saludo_dinamico = "¡Hola " + nombreCorto + "! 👑\n\nGracias por atenderte en la categoría " + categoriaNombre + ".";
let mensaje_accion = "⭐ *Ayúdanos a crecer:*\n¿Nos regalarías una reseña en Google?\n👉 " + LINK_GOOGLE_MAPS;

const premiosRaw = $('Leer Premios Staff').all().map(p => p.json);

let mapaPremios = premiosRaw.map(p => {
    const nombre = p['Nombre del Premio'] || p.nombre || "Premio";
    const costo = parseInt(p['Puntos Requeridos'] || p.costo_puntos || 0);
    return { nombre, costo, faltan: costo - puntosTotales, esGanado: costo <= puntosTotales };
});

const ganados = mapaPremios.filter(m => m.esGanado).sort((a, b) => b.costo - a.costo);
const pendientes = mapaPremios.filter(m => !m.esGanado).sort((a, b) => a.faltan - b.faltan);

let textoPremios = "";
if (ganados.length > 0) {
    textoPremios += "🎁 *¡YA PUEDES CANJEAR EN ESTA CATEGORÍA!* 👇\n";
    ganados.slice(0, 3).forEach(m => { textoPremios += `✅ ${m.nombre} *(${m.costo} pts)*\n`; });
    textoPremios += "\n";
}
if (pendientes.length > 0) {
    textoPremios += ganados.length > 0 ? "🚀 *Tu siguiente meta:*\n" : "🎯 *Estás muy cerca de:*\n";
    pendientes.slice(0, 2).forEach(m => { textoPremios += `🔒 ${m.nombre} *(Te faltan +${m.faltan} pts)*\n`; });
}

return {
    json: {
        saludo_dinamico,
        puntos_nuevos: puntosNuevos,
        puntos_totales: puntosTotales,
        lista_premios: textoPremios,
        mensaje_accion
    }
};
